namespace FocusGrowth {
public static class LocalJson {
 static readonly JavaScriptSerializer Ser=new JavaScriptSerializer{MaxJsonLength=16777216,RecursionLimit=64};
 public static object Parse(string text){try{lock(Ser)return Ser.DeserializeObject(text);}catch{throw new Fault("local_json_invalid");}}
 public static string Dump(object data){lock(Ser)return Ser.Serialize(data);}
 static object Ordered(object x){var d=x as Dictionary<string,object>;if(d!=null){var sorted=new SortedDictionary<string,object>(StringComparer.Ordinal);foreach(var p in d)sorted[p.Key]=Ordered(p.Value);return sorted;}if(x is IEnumerable&&!(x is string))return ((IEnumerable)x).Cast<object>().Select(Ordered).ToArray();return x;}
 public static string Canonical(object x){return Dump(Ordered(x));}
 public static string Pretty(object data){string json=Dump(data);var b=new StringBuilder();bool quoted=false,escape=false;int depth=0;foreach(char c in json){if(quoted){b.Append(c);if(escape)escape=false;else if(c=='\\')escape=true;else if(c=='"')quoted=false;continue;}if(c=='"'){quoted=true;b.Append(c);}else if(c=='{'||c=='['){depth++;b.Append(c).Append("\r\n").Append(' ',depth*2);}else if(c=='}'||c==']'){depth--;b.Append("\r\n").Append(' ',depth*2).Append(c);}else if(c==',')b.Append(c).Append("\r\n").Append(' ',depth*2);else if(c==':')b.Append(": ");else b.Append(c);}return b.ToString();}
 public static string Hash(byte[] bytes){using(var s=SHA256.Create())return BitConverter.ToString(s.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
 public static string Digest(object x){return Hash(Encoding.UTF8.GetBytes(Canonical(x)));}
}
public static class ProductionPolicy {
 public const string Version="0.3.1-preparation";
 public const string Notice="当前服务仅只读；正式远程状态以核验结果为准。";
 public static void DenyWrite(){throw new Fault("production_authorization_required");}
 public static bool BindingCurrent(Dictionary<string,object> approval,string preview,string backup,string local,string remote,int revision){return approval!=null&&J.Get(approval,"used") is bool&&!(bool)approval["used"]&&J.Str(J.Get(approval,"preview"))==preview&&J.Str(J.Get(approval,"backup"))==backup&&J.Str(J.Get(approval,"local"))==local&&J.Str(J.Get(approval,"remote"))==remote&&J.Get(approval,"revision") is int&&(int)approval["revision"]==revision;}
 // No approval-issuing endpoint, CLI flag, persisted switch or grant implementation exists in Option A.
 public static void Initialize(Dictionary<string,object> request){DenyWrite();}
}
public sealed class LocalVault {
 public readonly string Folder;
 public LocalVault(string folder){Folder=folder;Directory.CreateDirectory(folder);}
 public Dictionary<string,object> SaveVerified(string label,byte[] bytes){string id=DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffZ")+"-"+Guid.NewGuid().ToString("N");string p=Path.Combine(Folder,label+"-"+id+".dat");byte[] encrypted=ProtectedData.Protect(bytes,null,DataProtectionScope.CurrentUser);using(var f=new FileStream(p,FileMode.CreateNew,FileAccess.Write,FileShare.None)){f.Write(encrypted,0,encrypted.Length);f.Flush(true);}byte[] restored=ProtectedData.Unprotect(File.ReadAllBytes(p),null,DataProtectionScope.CurrentUser);bool equal=LocalJson.Hash(bytes)==LocalJson.Hash(restored);Array.Clear(restored,0,restored.Length);Schema.Require(equal,"backup_restore_hash_mismatch");return new Dictionary<string,object>{{"path",p},{"sha256",LocalJson.Hash(bytes)},{"createdUtc",DateTime.UtcNow.ToString("o")},{"restoreTest","PASS"},{"encrypted",true}};}
 public static byte[] Read(Dictionary<string,object> manifest){byte[] bytes=ProtectedData.Unprotect(File.ReadAllBytes((string)manifest["path"]),null,DataProtectionScope.CurrentUser);Schema.Require(LocalJson.Hash(bytes)==J.Str(manifest["sha256"]),"backup_hash_changed");return bytes;}
 public Dictionary<string,object> CaptureMetadata(string runtime,string sources){var entries=new List<object>();if(Directory.Exists(runtime))foreach(var path in Directory.GetFiles(runtime,"*",SearchOption.AllDirectories)){byte[] b=File.ReadAllBytes(path);entries.Add(new{group="runtime",name=path.Substring(runtime.Length).TrimStart('\\'),content=Convert.ToBase64String(b),sha256=LocalJson.Hash(b)});}foreach(string name in new[]{"Core.cs","Transport.cs","Bridge.cs","Program.cs","Tests.cs","Preparation.cs","build.ps1","FocusGrowthSync.exe","web/index.html","web/sync.js"}){string path=Path.Combine(sources,name);if(File.Exists(path)){byte[] b=File.ReadAllBytes(path);entries.Add(new{group="source",name=name,content=Convert.ToBase64String(b),sha256=LocalJson.Hash(b)});}}var m=SaveVerified("metadata",Encoding.UTF8.GetBytes(LocalJson.Dump(new{entries=entries})));byte[] restored=Read(m);try{foreach(var item in J.Arr(J.Obj(LocalJson.Parse(Encoding.UTF8.GetString(restored)))["entries"])){var row=J.Obj(item);Schema.Require(LocalJson.Hash(Convert.FromBase64String((string)row["content"]))==(string)row["sha256"],"metadata_roundtrip_failed");}}finally{Array.Clear(restored,0,restored.Length);}m["entryCount"]=entries.Count;return m;}
}
public static class PreparationModel {
 static bool Number(object x){return x is int||x is long||x is double||x is decimal;}
 public static void ValidateLocalOnly(Dictionary<string,object> db){
  var tasks=Schema.Map(Project(db),"tasks");var zones=new[]{"focus","noise","activate","repair"};
  string state=J.Str(J.Get(db,"state"));Schema.Require(String.IsNullOrEmpty(state)||zones.Contains(state),"local_state_invalid");
  var theme=J.Obj(J.Get(db,"theme"));foreach(string key in new[]{"bg","accent","focus","noise","activate","repair"})Schema.Require(System.Text.RegularExpressions.Regex.IsMatch(J.Str(J.Get(theme,key))??"","^#[0-9a-fA-F]{6}$"),"local_theme_invalid");
  var widgets=J.Obj(J.Get(db,"widgets"));foreach(string zone in zones)foreach(var entry in J.Arr(J.Get(widgets,zone))){var row=J.Arr(entry);Schema.Require(row.Count>=2&&row[0] is string&&row[1] is string,"local_widgets_invalid");}
  var goals=J.Obj(J.Get(db,"goals"));foreach(string key in new[]{"low","normal","high"}){var value=J.Get(goals,key);Schema.Require(Number(value)&&Convert.ToDouble(value)>=0&&Convert.ToDouble(value)<=1440,"local_goals_invalid");}
  foreach(var entry in J.Arr(db["tasks"])){var row=J.Obj(entry);var value=J.Get(row,"timerMs");if(value!=null)Schema.Require(Number(value)&&Convert.ToDouble(value)>=0&&!Double.IsInfinity(Convert.ToDouble(value)),"local_timer_invalid");}
  foreach(var entry in J.Arr(db["activity"])){var row=J.Obj(entry);string task=J.Str(J.Get(row,"taskId"));Schema.Require(String.IsNullOrEmpty(task)||tasks.ContainsKey(task),"local_activity_reference");string zone=J.Str(J.Get(row,"state"));Schema.Require(String.IsNullOrEmpty(zone)||zone=="unknown"||zones.Contains(zone),"local_activity_state_invalid");}
 }
 public static Dictionary<string,object> Project(Dictionary<string,object> db){Schema.Require(J.Get(db,"version") is int&&(int)db["version"]==1,"unsupported_app_version");var s=Schema.Empty();foreach(string c in Schema.Collections){var list=new List<object>();foreach(var item in J.Arr(J.Get(db,c))){var source=J.Obj(item);var row=new Dictionary<string,object>();foreach(string f in Schema.Fields[c])if(source.ContainsKey(f))row[f]=source[f];if(c=="tasks"){foreach(string f in new[]{"projectId","parentId"})if(!row.ContainsKey(f)||J.Get(row,f)==null||J.Str(row[f])=="")row[f]=null;row["date"]=J.Str(J.Get(row,"date"))??"";foreach(string f in new[]{"category","priority"})row[f]=J.Str(J.Get(row,f))??"";row["goal"]=J.Str(J.Get(row,"goal"))??"normal";if(!row.ContainsKey("actual"))row["actual"]=null;if(J.Get(row,"completedAt")==null)row.Remove("completedAt");}if(c=="projects"){row["deadline"]=J.Str(J.Get(row,"deadline"))??"";row["priority"]=J.Str(J.Get(row,"priority"))??"";if(!row.ContainsKey("weeklyMin"))row["weeklyMin"]=0;}list.Add(row);}s[c]=list.OrderBy(x=>J.Str(J.Get(J.Obj(x),"id")),StringComparer.Ordinal).ToArray();}Schema.Validate(s);return s;}
 public static void ValidateFull(Dictionary<string,object> db){Project(db);ValidateLocalOnly(db);foreach(string c in new[]{"activity","notes","history"})J.Arr(J.Get(db,c));var slots=new HashSet<string>();foreach(var x in J.Arr(db["activity"])){var a=J.Obj(x);DateTime d;Schema.Require(DateTime.TryParseExact(J.Str(J.Get(a,"date")),"yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.None,out d),"activity_date_invalid");int slot=J.Num(J.Get(a,"slot"));Schema.Require(slot>=0&&slot<144&&slots.Add((string)a["date"]+":"+slot),"activity_duplicate_or_invalid");}var ids=Schema.Map(Project(db),"tasks");string current=J.Str(J.Get(db,"currentTask"));if(!String.IsNullOrEmpty(current))Schema.Require(ids.ContainsKey(current),"current_task_reference");if(J.Get(db,"taskTimer")!=null){var t=J.Obj(db["taskTimer"]);Schema.Require(ids.ContainsKey(J.Str(J.Get(t,"taskId"))??"")&&Convert.ToDouble(J.Get(t,"startedAt"))>=0,"active_timer_reference");}}
 public static Dictionary<string,object> Difference(Dictionary<string,object> local,Dictionary<string,object> remote){Schema.Validate(local);Schema.Validate(remote);var rows=new List<object>();var totals=new Dictionary<string,object>();int conflicts=0;foreach(string col in Schema.Collections){var lm=Schema.Map(local,col);var rm=Schema.Map(remote,col);int adds=0,updates=0,incoming=0;foreach(string id in lm.Keys.Union(rm.Keys).OrderBy(x=>x,StringComparer.Ordinal)){if(!rm.ContainsKey(id)){adds++;rows.Add(new{collection=col,id=id,action="add_remote",before=(object)null,after=lm[id]});continue;}if(!lm.ContainsKey(id)){incoming++;rows.Add(new{collection=col,id=id,action="add_local_preview_only",before=(object)null,after=rm[id]});continue;}bool changed=false;foreach(string f in Schema.Fields[col]){object a=J.Get(rm[id],f),b=J.Get(lm[id],f);if(J.Equal(a,b))continue;changed=true;conflicts++;rows.Add(new{collection=col,id=id,field=f,action="initial_same_id_conflict",before=a,after=b});}if(changed)updates++;}totals[col]=new{local=lm.Count,remote=rm.Count,additions=adds,modifications=updates,incomingAdditions=incoming,conflicts=rows.Count(x=>J.Dump(x).Contains("initial_same_id_conflict")&&J.Dump(x).Contains("\"collection\":\""+col+"\"")),unsupported=0,deletesBlocked=0};}int overlaps=0;var plans=Schema.Map(local,"plans").Values.ToArray();for(int i=0;i<plans.Length;i++)for(int j=i+1;j<plans.Length;j++)if(J.Equal(plans[i]["date"],plans[j]["date"])&&(int)plans[i]["start"]<(int)plans[j]["start"]+(int)plans[j]["duration"]&&(int)plans[j]["start"]<(int)plans[i]["start"]+(int)plans[i]["duration"])overlaps++;return new Dictionary<string,object>{{"totals",totals},{"changes",rows},{"conflictCount",conflicts},{"overlapWarnings",overlaps},{"referenceValidation","PASS"},{"automaticScheduleChanges",false},{"deletionsInferred",false}};}
}
public sealed class PreparationService : IDisposable {
 readonly IProductionReader remote;readonly LocalVault vault;readonly string reports;readonly Dictionary<string,Tuple<string,Dictionary<string,object>>> requests=new Dictionary<string,Tuple<string,Dictionary<string,object>>>();public Dictionary<string,object> LastDetails,LastSummary;public Action Ready;string boundProfile;
 public PreparationService(string reportFolder,IProductionReader reader=null,LocalVault backupVault=null){reports=reportFolder;vault=backupVault??new LocalVault(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"FocusGrowthSync","preparation-v031","backups"));remote=reader??new Cloud("sync/state.json",true);}
 public void Initialize(Dictionary<string,object> request){ProductionPolicy.Initialize(request);}
 public object State(){remote.Verify();var s=remote.Read(null);Schema.Require(s.Sha!=null,"canonical_snapshot_missing");Schema.Validate(s.State);return new{version=ProductionPolicy.Version,mode="preparation",productionLocked=true,continuousSyncEnabled=false,notice=(bool)s.State["initialized"]?"正式远程已初始化；当前仅只读核验，持续双向同步未启用。":ProductionPolicy.Notice,remoteSha=s.Sha,remoteRevision=s.State["revision"],initialized=s.State["initialized"],state=s.State};}
 public Dictionary<string,object> Preview(Dictionary<string,object> request,string origin){lock(this){Schema.Require(request.Count==3&&request.ContainsKey("requestId")&&request.ContainsKey("source")&&request.ContainsKey("raw"),"invalid_preview_request");string id=J.Str(request["requestId"]);Schema.Id(id);string digest=LocalJson.Digest(request);Tuple<string,Dictionary<string,object>> prior;if(requests.TryGetValue(id,out prior)){Schema.Require(prior.Item1==digest,"preview_replay_payload_changed");return prior.Item2;}var source=J.Obj(request["source"]);Schema.Require(origin==Bridge.Pages&&J.Str(J.Get(source,"origin"))==Bridge.Pages&&J.Str(J.Get(source,"pathname"))=="/focus-growth/"&&J.Str(J.Get(source,"storageKey"))=="start-workbench-v1"&&J.Get(source,"present") is bool&&(bool)source["present"]&&J.Get(source,"synthetic") is bool&&!(bool)source["synthetic"],"production_source_unconfirmed");Schema.Id(J.Get(source,"profileId"));string sourceProfile=(string)source["profileId"];if(boundProfile!=null)Schema.Require(boundProfile==sourceProfile,"production_profile_mismatch");else boundProfile=sourceProfile;string raw=J.Str(request["raw"]);Schema.Require(!String.IsNullOrEmpty(raw),"browser_snapshot_absent");var db=J.Obj(LocalJson.Parse(raw));var backup=vault.SaveVerified("browser",Encoding.UTF8.GetBytes(raw));byte[] restored=LocalVault.Read(backup);bool fullValid=true;string validationError=null;try{var round=J.Obj(LocalJson.Parse(Encoding.UTF8.GetString(restored)));Schema.Require(LocalJson.Canonical(db)==LocalJson.Canonical(round),"restore_roundtrip_failed");PreparationModel.ValidateFull(round);}catch(Fault e){fullValid=false;validationError=e.Code;}catch{fullValid=false;validationError="local_schema_invalid";}finally{Array.Clear(restored,0,restored.Length);}backup["jsonAndAppValidation"]=fullValid?"PASS":"FAILED";var reasons=new List<string>();if(!fullValid)reasons.Add(validationError);if(J.Get(db,"demo") is bool&&(bool)db["demo"])reasons.Add("demo_workspace_not_production");Dictionary<string,object> projected=null;try{projected=PreparationModel.Project(db);}catch(Fault e){if(!reasons.Contains(e.Code))reasons.Add(e.Code);}if(projected!=null&&Schema.Collections.All(k=>J.Arr(projected[k]).Count==0))reasons.Add("empty_local_workspace_requires_source_verification");Snapshot snap=null;try{remote.Verify();snap=remote.Read(null);Schema.Require(snap.Sha!=null,"canonical_snapshot_missing");Schema.Validate(snap.State);}catch(Fault e){reasons.Add("remote_read_only_"+e.Code);}Dictionary<string,object> diff=null;if(projected!=null&&snap!=null){try{diff=PreparationModel.Difference(projected,snap.State);if((int)diff["conflictCount"]>0)reasons.Add("initial_id_conflicts_require_resolution");}catch(Fault e){reasons.Add(e.Code);}}string localHash=projected==null?null:LocalJson.Digest(projected);var binding=new Dictionary<string,object>{{"version",ProductionPolicy.Version},{"backup",backup["sha256"]},{"local",localHash},{"remote",snap==null?null:snap.Sha},{"revision",snap==null?null:snap.State["revision"]},{"source",source}};string previewHash=LocalJson.Digest(binding);var details=new Dictionary<string,object>{{"binding",binding},{"backup",backup},{"difference",diff},{"notice",ProductionPolicy.Notice}};var detailBackup=vault.SaveVerified("preview",Encoding.UTF8.GetBytes(LocalJson.Dump(details)));LastDetails=details;LastSummary=new Dictionary<string,object>{{"version",ProductionPolicy.Version},{"mode","preparation"},{"conclusion",reasons.Count==0?"READY_FOR_APPROVAL":"BLOCKED"},{"reasons",reasons},{"notice",ProductionPolicy.Notice},{"timestampLocal",DateTimeOffset.Now.ToString("o")},{"timestampUtc",DateTime.UtcNow.ToString("o")},{"repository","tang0709/focus-growth-data"},{"remoteSha",snap==null?null:snap.Sha},{"remoteRevision",snap==null?null:snap.State["revision"]},{"remoteInitialized",snap==null?null:snap.State["initialized"]},{"previewDigest",previewHash},{"localSnapshotDigest",localHash},{"backup",backup},{"source",source},{"detailsEncryptedPath",detailBackup["path"]},{"totals",diff==null?null:diff["totals"]},{"overlapWarnings",diff==null?null:diff["overlapWarnings"]},{"referenceValidation",diff==null?"FAILED":diff["referenceValidation"]},{"activityCount",J.Get(db,"activity")==null?0:J.Arr(db["activity"]).Count},{"notesPresent",J.Get(db,"notes")!=null&&J.Arr(db["notes"]).Count>0},{"activeTaskTimerPresent",J.Get(db,"taskTimer")!=null},{"allowedFields",Schema.Fields},{"excludedFields",new[]{"activity","notes","note","widgets","theme","state","currentTask","taskTimer","timerMs","history","goals"}},{"productionWriteAttempted",false},{"approvalIssued",false}};Directory.CreateDirectory(reports);File.WriteAllText(Path.Combine(reports,"PRODUCTION-DRY-RUN.json"),LocalJson.Dump(LastSummary),new UTF8Encoding(false));File.WriteAllText(Path.Combine(reports,"PRODUCTION-DRY-RUN.md"),"# V0.3.1 本机首次同步差异预览\n\n"+ProductionPolicy.Notice+"\n\n结论："+LastSummary["conclusion"]+"\n\n预览摘要：`"+previewHash+"`\n\n备份："+backup["path"]+"\n\n备份SHA-256："+backup["sha256"]+"；恢复校验："+backup["restoreTest"]+"；JSON及应用校验："+backup["jsonAndAppValidation"]+"\n\n来源："+source["origin"]+"/focus-growth/；key=start-workbench-v1；配置标识："+source["profileId"]+"\n\nUTC："+LastSummary["timestampUtc"]+"；本地："+LastSummary["timestampLocal"]+"\n\n远程SHA："+LastSummary["remoteSha"]+"；revision="+LastSummary["remoteRevision"]+"；initialized="+LastSummary["remoteInitialized"]+"\n\n计数（不含任务名称）：\n```json\n"+LocalJson.Dump(LastSummary["totals"])+"\n```\n\n引用校验："+LastSummary["referenceValidation"]+"；排程重叠警告："+LastSummary["overlapWarnings"]+"。不自动改期，不自动完成任何任务。\n\n详细逐字段前后值仅在本机加密文件及Windows预览窗口中显示："+detailBackup["path"]+"\n\n原因："+String.Join(", ",reasons)+"\n\n本文件和JSON均仅限本机，禁止提交Git或加入发布包。第二次授权须基于当前预览、备份、当前本地摘要及远程SHA；本阶段不会签发授权或启动正式同步。\n",new UTF8Encoding(false));requests[id]=Tuple.Create(digest,LastSummary);if(Ready!=null)Ready();return LastSummary;}}
 public void ShowDetails(IWin32Window owner){if(LastDetails==null)return;using(var f=new Form{Text="V0.3.1 本机差异预览 — "+ProductionPolicy.Notice,Width=1000,Height=720,StartPosition=FormStartPosition.CenterScreen}){var text=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,Dock=DockStyle.Fill,WordWrap=false,Text=LocalJson.Pretty(LastDetails)};f.Controls.Add(text);File.WriteAllText(Path.Combine(reports,"PRODUCTION-UI-STATUS.json"),LocalJson.Dump(new{previewDialogShown=true,notice=ProductionPolicy.Notice,version=ProductionPolicy.Version}));f.ShowDialog(owner);}}
 public void Dispose(){var d=remote as IDisposable;if(d!=null)d.Dispose();}
}
